      "type": "单选题",
      "stem": "摘要: ①作用于单靶点的药物在治疗复杂性疾病如肿瘤、糖尿病、感染性疾病时常常疗效不佳或毒性较大。②多靶点药物可以同时调节疾病网络系统中的多个环节，不易产生抗药性，对各靶点的作用产生协同效应，达到最佳的治疗效果。③本文对多靶点药物治疗的特点、分类情况、发现策略、筛选模型及已在临床使用的多靶点治疗药物进行综述，并探讨中药在多靶点药物治疗应用中的潜力。各个句子的作用为（ ）",
